function extractCoreWords(companyName) {
  const stopWords = new Set(['a','an','the','of','and','in','on','at','for','with','co','corp','inc','llc','ltd','company','services']);
  if (!companyName || typeof companyName !== 'string') return { longestWord: null, wordBefore: null, wordAfter: null };
  const words = companyName.trim().split(/\s+/).filter(w => {
    const c = w.toLowerCase().replace(/[^a-z0-9]/gi,'');
    return c && !stopWords.has(c);
  });
  if (!words.length) return { longestWord: null, wordBefore: null, wordAfter: null };
  let idx = 0;
  for (let i = 1; i < words.length; i++) if (words[i].length > words[idx].length) idx = i;
  return {
    longestWord: words[idx],
    wordBefore: idx > 0 ? words[idx-1] : null,
    wordAfter: idx < words.length-1 ? words[idx+1] : null
  };
}
const r = extractCoreWords($json.formattedCompany);
return [{ json: { ...$json, ...r } }];

