const formInput = $('Execute: sub-normalize-payload').first().json;
const original = $('When Executed by Another Workflow').first().json;
const assignment = $('Code: Assignment Owner').first().json;
const merged = $input.first().json;

const wpFormName = original.WPFormName || merged.WPFormName;
const isContactForm = wpFormName === 'ContactForm' || wpFormName === 'wpform_29710';
const isEmailOnly = wpFormName === 'WatchVideo' || wpFormName === 'GetADemo';
const leadFound = merged.found_lead_id;
const contactFound = merged.found_contact_id;
const accountStatus = merged.found_account_status;

const TWENTY_MIN_MS = 20 * 60 * 1000;
const now = Date.now();
function wasRecentlyContactFormUpdated(modIso, formVal) {
  if (!modIso || !formVal) return false;
  if (!String(formVal).includes('ContactForm')) return false;
  return (now - new Date(modIso).getTime()) <= TWENTY_MIN_MS;
}
const leadSuperseded = wasRecentlyContactFormUpdated(merged.found_lead_mod, merged.found_lead_form);
const contactSuperseded = wasRecentlyContactFormUpdated(merged.found_contact_mod, merged.found_contact_form);
const isSuperseded = isEmailOnly && (leadSuperseded || contactSuperseded);

let decisionPath, reason;
if (isSuperseded) { decisionPath = 'X_superseded_by_full_form'; reason = 'email-only, ContactForm within 20min — no SF write'; }
else if (isEmailOnly) {
  if (leadFound) { decisionPath = 'B_lite'; reason = 'email-only, existing Lead'; }
  else if (contactFound) { decisionPath = (accountStatus === 'Customer') ? 'C_lite' : 'D_lite'; reason = 'email-only, existing Contact'; }
